_sp = lambda f: f'<div style="flex:{f} 1 0"></div>'
_co = lambda n, name, ca, cl, fa, fl, cap: (f'<p><b>{name}:</b> ' + TX(f'נכסים שוטפים {ca}, התחייבויות שוטפות {cl}. {cap}') + '</p>') if MODE == 'pdf' else POP(n, f'<div class="mt-h"><b>{name}</b></div><div class="towers sm">' + _tw('נכסים שוטפים', [_sp(60 - fa), BK(0, '', ca, 'ca', fa)]) + '<div class="eqs"></div>'
                                              + _tw('התחייבויות שוטפות', [_sp(60 - fl), BK(0, '', cl, 'cl', fl)]) + f'</div><p class="mt-c">{TX(cap)}</p>', 'minip')
