_k = {'A1': 'העסק', 'B1': 'קיוסק', 'C1': 'רשת ארצית', 'A2': 'נכסים שוטפים (אלפי ש״ח)', 'A3': 'התחייבויות שוטפות (אלפי ש״ח)', 'A5': 'נכסים שוטפים לכל 1 ש״ח של התחייבות שוטפת'}
